import { ChangeDetectionStrategy, Component, Input } from '@angular/core';

export type CxsBreadcrumbSize = 'sm' | 'md' | 'lg';
export type CxsBreadcrumbVariant = 'default' | 'muted';

export interface CxsBreadcrumbItem {
  label: string;
  href?: string;
  target?: string;
  rel?: string;
  ariaLabel?: string;
  disabled?: boolean;
}

const BASE_CLASSES = 'flex flex-wrap items-center gap-x-1 gap-y-1';
const ITEM_CLASSES = 'flex items-center gap-1';
const LINK_BASE_CLASSES =
  'rounded-[var(--cxs-radius-md)] transition-colors focus-visible:outline focus-visible:outline-2 ' +
  'focus-visible:outline-offset-2 focus-visible:outline-[var(--cxs-color-focus)]';
const NON_LINK_CLASSES = 'text-[var(--cxs-color-on-surface-muted)]';
const SEPARATOR_CLASSES = 'text-[var(--cxs-color-on-surface-muted)] select-none';
const DISABLED_CLASSES = 'text-[var(--cxs-color-on-surface-muted)] opacity-60';

const SIZE_CLASSES: Record<CxsBreadcrumbSize, string> = {
  sm: 'text-xs',
  md: 'text-sm',
  lg: 'text-base'
};

const LINK_VARIANT_CLASSES: Record<CxsBreadcrumbVariant, string> = {
  default:
    'text-[var(--cxs-color-primary)] hover:text-[var(--cxs-color-primary-hover)]',
  muted:
    'text-[var(--cxs-color-on-surface-muted)] hover:text-[var(--cxs-color-on-surface)]'
};

const CURRENT_VARIANT_CLASSES: Record<CxsBreadcrumbVariant, string> = {
  default: 'text-[var(--cxs-color-on-surface)]',
  muted: 'text-[var(--cxs-color-on-surface-muted)]'
};

@Component({
  selector: 'cxs-breadcrumb',
  standalone: true,
  templateUrl: './breadcrumb.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CxsBreadcrumbComponent {
  @Input() items: CxsBreadcrumbItem[] = [];
  @Input() separator = '/';
  @Input() ariaLabel = 'Breadcrumb';
  @Input() size: CxsBreadcrumbSize = 'md';
  @Input() variant: CxsBreadcrumbVariant = 'default';
  @Input() disabled = false;

  get listClass(): string {
    return [BASE_CLASSES, SIZE_CLASSES[this.size], this.disabled ? 'opacity-60' : '']
      .filter(Boolean)
      .join(' ');
  }

  get itemClass(): string {
    return ITEM_CLASSES;
  }

  get separatorClass(): string {
    return SEPARATOR_CLASSES;
  }

  isLink(item: CxsBreadcrumbItem, isLast: boolean): boolean {
    return !!item.href && !isLast && !item.disabled && !this.disabled;
  }

  getLinkClass(item: CxsBreadcrumbItem): string {
    return [
      LINK_BASE_CLASSES,
      LINK_VARIANT_CLASSES[this.variant],
      item.disabled || this.disabled ? DISABLED_CLASSES : ''
    ]
      .filter(Boolean)
      .join(' ');
  }

  getLabelClass(item: CxsBreadcrumbItem, isLast: boolean): string {
    if (isLast) {
      return [
        CURRENT_VARIANT_CLASSES[this.variant],
        item.disabled || this.disabled ? DISABLED_CLASSES : ''
      ]
        .filter(Boolean)
        .join(' ');
    }

    return [NON_LINK_CLASSES, item.disabled || this.disabled ? DISABLED_CLASSES : '']
      .filter(Boolean)
      .join(' ');
  }

  getItemRel(item: CxsBreadcrumbItem): string | null {
    if (item.target === '_blank') {
      return item.rel ?? 'noopener noreferrer';
    }

    return item.rel ?? null;
  }
}

import {
  AfterViewInit,
  Attribute,
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  Input,
  OnChanges,
  OnDestroy,
  Output,
  SimpleChanges
} from '@angular/core';

export interface CxsCarouselItem {
  title?: string;
  description?: string;
  image?: string;
  alt?: string;
}

const WRAPPER_BASE_CLASSES = 'relative overflow-hidden rounded-[var(--cxs-radius-md)]';
const TRACK_CLASSES = 'flex transition-transform duration-500 ease-out';
const SLIDE_BASE_CLASSES = 'w-full flex-shrink-0';
const IMAGE_CLASSES = 'h-56 w-full object-cover';
const CONTENT_CLASSES =
  'absolute inset-x-0 bottom-0 bg-[rgba(15,23,42,0.6)] px-4 py-3 text-sm text-white';

const CONTROL_CLASSES =
  'absolute top-1/2 -translate-y-1/2 inline-flex h-9 w-9 items-center justify-center rounded-full ' +
  'bg-[rgba(15,23,42,0.7)] text-white transition hover:bg-[rgba(15,23,42,0.85)] ' +
  'focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 ' +
  'focus-visible:outline-[var(--cxs-color-focus)]';

const INDICATOR_CONTAINER_CLASSES =
  'absolute bottom-3 left-1/2 flex -translate-x-1/2 items-center gap-2';
const INDICATOR_BASE_CLASSES =
  'h-2 w-2 rounded-full bg-white/50 transition-colors';
const INDICATOR_ACTIVE_CLASSES = 'bg-white';

@Component({
  selector: 'cxs-carousel',
  standalone: true,
  templateUrl: './carousel.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CxsCarouselComponent implements OnChanges, AfterViewInit, OnDestroy {
  @Input() items: CxsCarouselItem[] = [];
  @Input() activeIndex = 0;
  @Input() autoplay = false;
  @Input() interval = 4000;
  @Input() loop = true;
  @Input() showControls = true;
  @Input() showIndicators = true;
  @Input() ariaLabel = 'Carousel';

  @Output() activeIndexChange = new EventEmitter<number>();

  private timerId: ReturnType<typeof setInterval> | null = null;

  constructor(@Attribute('class') private readonly hostClass: string | null) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['items'] || changes['autoplay'] || changes['interval']) {
      this.resetAutoplay();
    }
    if (changes['activeIndex']) {
      this.activeIndex = this.clampIndex(this.activeIndex);
    }
  }

  ngAfterViewInit(): void {
    this.resetAutoplay();
  }

  ngOnDestroy(): void {
    this.clearAutoplay();
  }

  get wrapperClass(): string {
    return [WRAPPER_BASE_CLASSES, this.hostClass].filter(Boolean).join(' ');
  }

  get trackStyle(): string {
    return `translateX(-${this.activeIndex * 100}%)`;
  }

  get trackClass(): string {
    return TRACK_CLASSES;
  }

  get slideClass(): string {
    return SLIDE_BASE_CLASSES;
  }

  get imageClass(): string {
    return IMAGE_CLASSES;
  }

  get contentClass(): string {
    return CONTENT_CLASSES;
  }

  get controlClass(): string {
    return CONTROL_CLASSES;
  }

  get indicatorContainerClass(): string {
    return INDICATOR_CONTAINER_CLASSES;
  }

  indicatorClass(isActive: boolean): string {
    return [INDICATOR_BASE_CLASSES, isActive ? INDICATOR_ACTIVE_CLASSES : '']
      .filter(Boolean)
      .join(' ');
  }

  previous(): void {
    this.goTo(this.activeIndex - 1);
  }

  next(): void {
    this.goTo(this.activeIndex + 1);
  }

  goTo(index: number): void {
    const nextIndex = this.normalizeIndex(index);
    this.activeIndex = nextIndex;
    this.activeIndexChange.emit(nextIndex);
  }

  private normalizeIndex(index: number): number {
    if (!this.items.length) {
      return 0;
    }

    if (this.loop) {
      const total = this.items.length;
      return (index + total) % total;
    }

    return this.clampIndex(index);
  }

  private clampIndex(index: number): number {
    if (!this.items.length) {
      return 0;
    }

    return Math.min(Math.max(0, index), this.items.length - 1);
  }

  private resetAutoplay(): void {
    this.clearAutoplay();

    if (!this.autoplay || this.items.length <= 1) {
      return;
    }

    const intervalMs = Math.max(1000, this.interval);
    this.timerId = setInterval(() => {
      this.next();
    }, intervalMs);
  }

  private clearAutoplay(): void {
    if (this.timerId) {
      clearInterval(this.timerId);
      this.timerId = null;
    }
  }
}

import { Directive, Input, TemplateRef } from '@angular/core';
import type { CxsDataTableColumn } from './data-table.component';

export interface CxsDataTableCellContext {
  $implicit: Record<string, unknown>;
  value: unknown;
  column: CxsDataTableColumn;
}

@Directive({
  selector: '[cxsDataTableCell]',
  standalone: true
})
export class CxsDataTableCellDirective {
  @Input('cxsDataTableCell') columnKey = '';

  constructor(public readonly template: TemplateRef<CxsDataTableCellContext>) {}
}

import { NgTemplateOutlet } from '@angular/common';
import {
  Attribute,
  ChangeDetectionStrategy,
  Component,
  ContentChildren,
  EventEmitter,
  Input,
  OnChanges,
  Output,
  QueryList,
  SimpleChanges,
  TemplateRef
} from '@angular/core';
import { CxsDataTableCellDirective } from './data-table-cell.directive';
import type { CxsDataTableCellContext } from './data-table-cell.directive';

export type CxsDataTableAlign = 'left' | 'center' | 'right';
export type CxsDataTableSortDirection = 'asc' | 'desc';
export type CxsDataTableFilterType = 'text' | 'select' | 'number';
export type CxsDataTablePin = 'left' | 'right';

export interface CxsDataTableColumn {
  key: string;
  label: string;
  align?: CxsDataTableAlign;
  width?: string;
  sortable?: boolean;
  filterable?: boolean;
  filterType?: CxsDataTableFilterType;
  filterOptions?: Array<{ label: string; value: string }>;
  resizable?: boolean;
  pinned?: CxsDataTablePin;
  visible?: boolean;
  minWidth?: number;
  headerClass?: string;
  cellClass?: string;
  formatter?: (value: unknown, row: Record<string, unknown>) => string;
}

export interface CxsDataTableSort {
  key: string;
  direction: CxsDataTableSortDirection;
}

const WRAPPER_BASE_CLASSES = 'w-full overflow-hidden';
const WRAPPER_BORDERED_CLASSES =
  'rounded-[var(--cxs-radius-md)] border border-[var(--cxs-color-border)]';

const TABLE_BASE_CLASSES = 'w-full border-collapse text-sm text-[var(--cxs-color-on-surface)]';
const TABLE_COMPACT_CLASSES = 'text-xs';

const HEADER_ROW_CLASSES =
  'border-b border-[var(--cxs-color-border)] text-xs font-semibold ' +
  'text-[var(--cxs-color-on-surface-muted)]';
const HEADER_CELL_BASE_CLASSES = 'px-3 py-2 text-left';
const HEADER_BUTTON_CLASSES =
  'inline-flex items-center gap-2 rounded-[var(--cxs-radius-md)] px-2 py-1 ' +
  'transition-colors hover:bg-[var(--cxs-color-surface-hover)] ' +
  'focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 ' +
  'focus-visible:outline-[var(--cxs-color-focus)]';
const HEADER_FILTER_INPUT_CLASSES =
  'w-full rounded-[var(--cxs-radius-md)] border border-[var(--cxs-color-border)] ' +
  'bg-[var(--cxs-color-surface)] px-2 py-1 text-xs text-[var(--cxs-color-on-surface)] ' +
  'placeholder:text-[var(--cxs-color-on-surface-muted)] focus-visible:outline focus-visible:outline-2 ' +
  'focus-visible:outline-offset-2 focus-visible:outline-[var(--cxs-color-focus)]';

const BODY_ROW_BASE_CLASSES = 'border-b border-[var(--cxs-color-border)] last:border-b-0';
const BODY_ROW_STRIPED_CLASSES = 'odd:bg-[var(--cxs-color-surface)] even:bg-[var(--cxs-color-surface-hover)]';

const BODY_CELL_BASE_CLASSES = 'px-3 py-2 align-top';
const BODY_CELL_COMPACT_CLASSES = 'px-2 py-1.5';

const ALIGN_CLASSES: Record<CxsDataTableAlign, string> = {
  left: 'text-left',
  center: 'text-center',
  right: 'text-right'
};

const EMPTY_ROW_CLASSES = 'text-sm text-[var(--cxs-color-on-surface-muted)]';
const PAGINATION_CLASSES =
  'mt-4 flex flex-wrap items-center justify-between gap-3 text-sm text-[var(--cxs-color-on-surface)]';
const PAGE_BUTTON_CLASSES =
  'inline-flex items-center justify-center rounded-[var(--cxs-radius-md)] border border-[var(--cxs-color-border)] ' +
  'px-3 py-1.5 text-sm transition-colors hover:bg-[var(--cxs-color-surface-hover)] ' +
  'disabled:cursor-not-allowed disabled:opacity-60';
const PAGE_SELECT_CLASSES =
  'rounded-[var(--cxs-radius-md)] border border-[var(--cxs-color-border)] bg-[var(--cxs-color-surface)] ' +
  'px-2 py-1 text-sm';
const TOOLBAR_CLASSES =
  'mb-3 flex flex-wrap items-center justify-between gap-3 text-sm text-[var(--cxs-color-on-surface)]';
const TOOLBAR_GROUP_CLASSES = 'flex flex-wrap items-center gap-2';
const TOOLBAR_INPUT_CLASSES =
  'w-full rounded-[var(--cxs-radius-md)] border border-[var(--cxs-color-border)] ' +
  'bg-[var(--cxs-color-surface)] px-3 py-2 text-sm text-[var(--cxs-color-on-surface)] ' +
  'placeholder:text-[var(--cxs-color-on-surface-muted)] focus-visible:outline focus-visible:outline-2 ' +
  'focus-visible:outline-offset-2 focus-visible:outline-[var(--cxs-color-focus)]';
const TOOLBAR_BUTTON_CLASSES =
  'inline-flex items-center justify-center rounded-[var(--cxs-radius-md)] border border-[var(--cxs-color-border)] ' +
  'px-3 py-2 text-sm transition-colors hover:bg-[var(--cxs-color-surface-hover)]';
const BULK_BAR_CLASSES =
  'mb-3 flex flex-wrap items-center justify-between gap-3 rounded-[var(--cxs-radius-md)] ' +
  'border border-[var(--cxs-color-border)] bg-[var(--cxs-color-surface)] px-3 py-2 text-sm';
const RESIZE_HANDLE_CLASSES =
  'absolute right-0 top-0 h-full w-2 cursor-col-resize touch-none';

@Component({
  selector: 'cxs-data-table',
  standalone: true,
  templateUrl: './data-table.component.html',
  imports: [NgTemplateOutlet],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CxsDataTableComponent implements OnChanges {
  @Input() columns: CxsDataTableColumn[] = [];
  @Input() data: Array<Record<string, unknown>> = [];
  @Input() caption?: string;
  @Input() ariaLabel = 'Data table';
  @Input() striped = false;
  @Input() bordered = false;
  @Input() compact = false;
  @Input() loading = false;
  @Input() emptyMessage = 'No data available';
  @Input() emptyCell = '—';

  @Input() pageSize = 10;
  @Input() pageIndex = 1;
  @Input() pageSizeOptions: number[] = [10, 20, 50];
  @Input() showPagination = true;
  @Input() showPageSize = true;
  @Input() manualPagination = false;
  @Input() total?: number;

  @Input() sortKey?: string;
  @Input() sortDirection: CxsDataTableSortDirection = 'asc';
  @Input() manualSort = false;

  @Input() showToolbar = true;
  @Input() showFilters = true;
  @Input() showColumnVisibility = true;
  @Input() showGlobalSearch = true;
  @Input() manualFilter = false;

  @Input() selectable = false;
  @Input() rowKey = 'id';
  @Input() selectedKeys: Array<string | number> = [];
  @Input() bulkActions: Array<{ id: string; label: string }> = [];

  @Output() pageChange = new EventEmitter<number>();
  @Output() pageSizeChange = new EventEmitter<number>();
  @Output() sortChange = new EventEmitter<CxsDataTableSort>();
  @Output() filterChange = new EventEmitter<{
    global: string;
    columns: Record<string, string>;
  }>();
  @Output() selectionChange = new EventEmitter<Array<string | number>>();
  @Output() bulkAction = new EventEmitter<{
    id: string;
    selected: Array<Record<string, unknown>>;
  }>();

  @ContentChildren(CxsDataTableCellDirective)
  private readonly cellTemplates?: QueryList<CxsDataTableCellDirective>;

  protected currentPage = 1;
  protected currentPageSize = 10;
  protected globalFilter = '';
  protected columnFilters: Record<string, string> = {};
  protected columnVisibility: Record<string, boolean> = {};
  protected columnWidths: Record<string, string> = {};
  protected isResizing = false;
  protected resizingColumn?: string;
  protected pinnedOffsetsLeft: Record<string, number> = {};
  protected pinnedOffsetsRight: Record<string, number> = {};
  protected filtersOpen = true;

  private resizeStartX = 0;
  private resizeStartWidth = 0;

  constructor(@Attribute('class') private readonly hostClass: string | null) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['pageIndex']) {
      this.currentPage = Math.max(1, this.pageIndex);
    }
    if (changes['pageSize']) {
      this.currentPageSize = Math.max(1, this.pageSize);
    }
    if (changes['columns']) {
      this.initializeVisibility();
      this.initializeWidths();
      this.updatePinnedOffsets();
    }
    if (changes['showFilters']) {
      this.filtersOpen = this.showFilters;
    }
    if (changes['selectedKeys']) {
      this.selectedKeys = [...this.selectedKeys];
    }
  }

  get wrapperClass(): string {
    return [
      WRAPPER_BASE_CLASSES,
      this.bordered ? WRAPPER_BORDERED_CLASSES : '',
      this.hostClass
    ]
      .filter(Boolean)
      .join(' ');
  }

  get tableClass(): string {
    return [TABLE_BASE_CLASSES, this.compact ? TABLE_COMPACT_CLASSES : '']
      .filter(Boolean)
      .join(' ');
  }

  get headerRowClass(): string {
    return HEADER_ROW_CLASSES;
  }

  get bodyRowClass(): string {
    return [
      BODY_ROW_BASE_CLASSES,
      this.striped ? BODY_ROW_STRIPED_CLASSES : ''
    ]
      .filter(Boolean)
      .join(' ');
  }

  get emptyRowClass(): string {
    return EMPTY_ROW_CLASSES;
  }

  get paginationClass(): string {
    return PAGINATION_CLASSES;
  }

  get pageButtonClass(): string {
    return PAGE_BUTTON_CLASSES;
  }

  get pageSelectClass(): string {
    return PAGE_SELECT_CLASSES;
  }

  get toolbarClass(): string {
    return TOOLBAR_CLASSES;
  }

  get toolbarGroupClass(): string {
    return TOOLBAR_GROUP_CLASSES;
  }

  get toolbarInputClass(): string {
    return TOOLBAR_INPUT_CLASSES;
  }

  get toolbarButtonClass(): string {
    return TOOLBAR_BUTTON_CLASSES;
  }

  get bulkBarClass(): string {
    return BULK_BAR_CLASSES;
  }

  get resizeHandleClass(): string {
    return RESIZE_HANDLE_CLASSES;
  }

  get colSpan(): number {
    return Math.max(this.visibleColumns.length + (this.selectable ? 1 : 0), 1);
  }

  get totalItems(): number {
    if (this.manualPagination && this.total !== undefined) {
      return this.total;
    }

    return this.data.length;
  }

  get totalPages(): number {
    return Math.max(1, Math.ceil(this.totalItems / this.currentPageSize));
  }

  get pageLabel(): string {
    return `Page ${this.currentPage} of ${this.totalPages}`;
  }

  get displayRows(): Array<Record<string, unknown>> {
    const filtered = this.manualFilter ? this.data : this.getFilteredData(this.data);
    const sorted = this.manualSort ? filtered : this.getSortedData(filtered);
    if (this.manualPagination) {
      return sorted;
    }

    const start = (this.currentPage - 1) * this.currentPageSize;
    return sorted.slice(start, start + this.currentPageSize);
  }

  get visibleColumns(): CxsDataTableColumn[] {
    return this.columns.filter((column) => this.columnVisibility[column.key] !== false);
  }

  get selectedCount(): number {
    return this.selectedKeys.length;
  }

  get allVisibleSelected(): boolean {
    if (!this.displayRows.length) {
      return false;
    }

    return this.displayRows.every((row) => this.isSelected(row));
  }

  get someVisibleSelected(): boolean {
    return this.displayRows.some((row) => this.isSelected(row)) && !this.allVisibleSelected;
  }

  headerCellClass(column: CxsDataTableColumn): string {
    return [
      HEADER_CELL_BASE_CLASSES,
      ALIGN_CLASSES[column.align ?? 'left'],
      column.headerClass ?? ''
    ]
      .filter(Boolean)
      .join(' ');
  }

  headerButtonClass(): string {
    return HEADER_BUTTON_CLASSES;
  }

  headerFilterInputClass(): string {
    return HEADER_FILTER_INPUT_CLASSES;
  }

  bodyCellClass(column: CxsDataTableColumn): string {
    return [
      BODY_CELL_BASE_CLASSES,
      this.compact ? BODY_CELL_COMPACT_CLASSES : '',
      ALIGN_CLASSES[column.align ?? 'left'],
      column.cellClass ?? ''
    ]
      .filter(Boolean)
      .join(' ');
  }

  cellTemplate(columnKey: string): TemplateRef<CxsDataTableCellContext> | null {
    if (!this.cellTemplates) {
      return null;
    }

    return this.cellTemplates.find((template) => template.columnKey === columnKey)?.template ?? null;
  }

  cellValue(row: Record<string, unknown>, column: CxsDataTableColumn): string {
    const value = row[column.key];
    if (column.formatter) {
      return column.formatter(value, row);
    }

    if (value === null || value === undefined || value === '') {
      return this.emptyCell;
    }

    return String(value);
  }

  columnWidth(column: CxsDataTableColumn): string | null {
    return this.columnWidths[column.key] ?? column.width ?? null;
  }

  columnMinWidth(column: CxsDataTableColumn): string | null {
    if (column.minWidth) {
      return `${column.minWidth}px`;
    }
    return null;
  }

  pinnedStyle(column: CxsDataTableColumn): Record<string, string> | null {
    if (!column.pinned) {
      return null;
    }

    if (column.pinned === 'left') {
      return { left: `${this.pinnedOffsetsLeft[column.key] ?? 0}px` };
    }

    return { right: `${this.pinnedOffsetsRight[column.key] ?? 0}px` };
  }

  pinnedLeft(column: CxsDataTableColumn): string | null {
    const style = this.pinnedStyle(column);
    return style ? style['left'] ?? null : null;
  }

  pinnedRight(column: CxsDataTableColumn): string | null {
    const style = this.pinnedStyle(column);
    return style ? style['right'] ?? null : null;
  }

  pinnedClass(column: CxsDataTableColumn): string {
    if (!column.pinned) {
      return '';
    }

    return 'sticky z-10';
  }

  ariaSort(column: CxsDataTableColumn): 'ascending' | 'descending' | 'none' | null {
    if (!column.sortable) {
      return null;
    }

    if (this.sortKey !== column.key) {
      return 'none';
    }

    return this.sortDirection === 'asc' ? 'ascending' : 'descending';
  }

  onSort(column: CxsDataTableColumn): void {
    if (!column.sortable) {
      return;
    }

    if (this.sortKey === column.key) {
      this.sortDirection = this.sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      this.sortKey = column.key;
      this.sortDirection = 'asc';
    }

    this.sortChange.emit({
      key: this.sortKey,
      direction: this.sortDirection
    });
  }

  goToPage(page: number): void {
    const nextPage = Math.min(Math.max(1, page), this.totalPages);
    this.currentPage = nextPage;
    this.pageChange.emit(nextPage);
  }

  nextPage(): void {
    this.goToPage(this.currentPage + 1);
  }

  previousPage(): void {
    this.goToPage(this.currentPage - 1);
  }

  onPageSizeChange(value: string): void {
    const nextSize = Number(value);
    if (!Number.isFinite(nextSize) || nextSize <= 0) {
      return;
    }

    this.currentPageSize = nextSize;
    this.pageSizeChange.emit(nextSize);
    this.goToPage(1);
  }

  onGlobalFilterChange(value: string): void {
    this.globalFilter = value;
    this.emitFilterChange();
    this.goToPage(1);
  }

  onColumnFilterChange(columnKey: string, value: string): void {
    this.columnFilters[columnKey] = value;
    this.emitFilterChange();
    this.goToPage(1);
  }

  columnFilterValue(columnKey: string): string {
    return this.columnFilters[columnKey] || '';
  }

  toggleColumnVisibility(columnKey: string): void {
    this.columnVisibility[columnKey] = !this.columnVisibility[columnKey];
    this.updatePinnedOffsets();
  }

  toggleSelectAll(): void {
    if (this.allVisibleSelected) {
      this.selectedKeys = this.selectedKeys.filter(
        (key) => !this.displayRows.some((row) => this.rowIdentifier(row) === key)
      );
    } else {
      const keysToAdd = this.displayRows
        .map((row) => this.rowIdentifier(row))
        .filter((key) => !this.selectedKeys.includes(key));
      this.selectedKeys = [...this.selectedKeys, ...keysToAdd];
    }

    this.selectionChange.emit([...this.selectedKeys]);
  }

  toggleRowSelection(row: Record<string, unknown>): void {
    const key = this.rowIdentifier(row);
    if (this.selectedKeys.includes(key)) {
      this.selectedKeys = this.selectedKeys.filter((id) => id !== key);
    } else {
      this.selectedKeys = [...this.selectedKeys, key];
    }

    this.selectionChange.emit([...this.selectedKeys]);
  }

  isSelected(row: Record<string, unknown>): boolean {
    return this.selectedKeys.includes(this.rowIdentifier(row));
  }

  runBulkAction(actionId: string): void {
    this.bulkAction.emit({
      id: actionId,
      selected: this.data.filter((row) => this.selectedKeys.includes(this.rowIdentifier(row)))
    });
  }

  onResizeStart(event: MouseEvent, column: CxsDataTableColumn): void {
    if (column.resizable === false) {
      return;
    }

    event.preventDefault();
    const header = (event.target as HTMLElement).closest('th') as HTMLElement | null;
    if (!header) {
      return;
    }

    this.isResizing = true;
    this.resizingColumn = column.key;
    this.resizeStartX = event.clientX;
    this.resizeStartWidth = header.getBoundingClientRect().width;

    const onMove = (moveEvent: MouseEvent) => {
      if (!this.isResizing || !this.resizingColumn) {
        return;
      }
      const delta = moveEvent.clientX - this.resizeStartX;
      const minWidth = column.minWidth ?? 80;
      const nextWidth = Math.max(minWidth, this.resizeStartWidth + delta);
      this.columnWidths[this.resizingColumn] = `${Math.round(nextWidth)}px`;
      this.updatePinnedOffsets();
    };

    const onUp = () => {
      this.isResizing = false;
      this.resizingColumn = undefined;
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
    };

    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  }

  private getSortedData(rows: Array<Record<string, unknown>>): Array<Record<string, unknown>> {
    if (!this.sortKey) {
      return rows;
    }

    const direction = this.sortDirection === 'asc' ? 1 : -1;
    return [...rows].sort((a, b) => {
      const valueA = a[this.sortKey ?? ''];
      const valueB = b[this.sortKey ?? ''];
      const normalizedA = valueA === null || valueA === undefined ? '' : String(valueA);
      const normalizedB = valueB === null || valueB === undefined ? '' : String(valueB);
      return normalizedA.localeCompare(normalizedB, undefined, { numeric: true }) * direction;
    });
  }

  private getFilteredData(rows: Array<Record<string, unknown>>): Array<Record<string, unknown>> {
    const global = this.globalFilter.trim().toLowerCase();
    const filters = this.columnFilters;

    return rows.filter((row) => {
      if (global) {
        const matchesGlobal = this.visibleColumns.some((column) => {
          const value = row[column.key];
          return String(value ?? '').toLowerCase().includes(global);
        });
        if (!matchesGlobal) {
          return false;
        }
      }

      return this.visibleColumns.every((column) => {
        if (!column.filterable) {
          return true;
        }
        const filterValue = (filters[column.key] ?? '').trim().toLowerCase();
        if (!filterValue) {
          return true;
        }
        const raw = row[column.key];
        const normalized = String(raw ?? '').toLowerCase();
        if (column.filterType === 'select') {
          return normalized === filterValue;
        }
        return normalized.includes(filterValue);
      });
    });
  }

  private emitFilterChange(): void {
    this.filterChange.emit({
      global: this.globalFilter,
      columns: { ...this.columnFilters }
    });
  }

  private initializeVisibility(): void {
    this.columnVisibility = this.columns.reduce((acc, column) => {
      acc[column.key] = column.visible !== false;
      return acc;
    }, {} as Record<string, boolean>);
  }

  private initializeWidths(): void {
    this.columnWidths = this.columns.reduce((acc, column) => {
      if (column.width) {
        acc[column.key] = column.width;
      }
      return acc;
    }, {} as Record<string, string>);
  }

  private updatePinnedOffsets(): void {
    const leftOffsets: Record<string, number> = {};
    const rightOffsets: Record<string, number> = {};
    let left = 0;
    let right = 0;
    const columns = this.visibleColumns;

    columns.forEach((column) => {
      if (column.pinned === 'left') {
        leftOffsets[column.key] = left;
        left += this.getWidthValue(column);
      }
    });

    [...columns].reverse().forEach((column) => {
      if (column.pinned === 'right') {
        rightOffsets[column.key] = right;
        right += this.getWidthValue(column);
      }
    });

    this.pinnedOffsetsLeft = leftOffsets;
    this.pinnedOffsetsRight = rightOffsets;
  }

  private getWidthValue(column: CxsDataTableColumn): number {
    const width = this.columnWidths[column.key] ?? column.width;
    if (!width) {
      return 160;
    }
    const match = width.match(/(\d+)(px)?/);
    if (match) {
      return Number(match[1]);
    }
    return 160;
  }

  private rowIdentifier(row: Record<string, unknown>): string | number {
    const value = row[this.rowKey];
    if (value === undefined || value === null) {
      return JSON.stringify(row);
    }
    return value as string | number;
  }
}

import { NgTemplateOutlet } from '@angular/common';
import {
  Attribute,
  ChangeDetectionStrategy,
  Component,
  ContentChildren,
  EventEmitter,
  Input,
  OnChanges,
  Output,
  QueryList,
  SimpleChanges,
  TemplateRef
} from '@angular/core';
import { CxsDataTableCellDirective } from './data-table-cell.directive';
import type { CxsDataTableCellContext } from './data-table-cell.directive';

export type CxsDataTableAlign = 'left' | 'center' | 'right';
export type CxsDataTableSortDirection = 'asc' | 'desc';
export type CxsDataTableFilterType = 'text' | 'select' | 'number';
export type CxsDataTablePin = 'left' | 'right';

export interface CxsDataTableColumn {
  key: string;
  label: string;
  align?: CxsDataTableAlign;
  width?: string;
  sortable?: boolean;
  filterable?: boolean;
  filterType?: CxsDataTableFilterType;
  filterOptions?: Array<{ label: string; value: string }>;
  resizable?: boolean;
  pinned?: CxsDataTablePin;
  visible?: boolean;
  minWidth?: number;
  headerClass?: string;
  cellClass?: string;
  formatter?: (value: unknown, row: Record<string, unknown>) => string;
}

export interface CxsDataTableSort {
  key: string;
  direction: CxsDataTableSortDirection;
}

const WRAPPER_BASE_CLASSES = 'w-full overflow-hidden';
const WRAPPER_BORDERED_CLASSES =
  'rounded-[var(--cxs-radius-md)] border border-[var(--cxs-color-border)]';

const TABLE_BASE_CLASSES = 'w-full border-collapse text-sm text-[var(--cxs-color-on-surface)]';
const TABLE_COMPACT_CLASSES = 'text-xs';

const HEADER_ROW_CLASSES =
  'border-b border-[var(--cxs-color-border)] text-xs font-semibold ' +
  'text-[var(--cxs-color-on-surface-muted)]';
const HEADER_CELL_BASE_CLASSES = 'px-3 py-2 text-left';
const HEADER_BUTTON_CLASSES =
  'inline-flex items-center gap-2 rounded-[var(--cxs-radius-md)] px-2 py-1 ' +
  'transition-colors hover:bg-[var(--cxs-color-surface-hover)] ' +
  'focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 ' +
  'focus-visible:outline-[var(--cxs-color-focus)]';
const HEADER_FILTER_INPUT_CLASSES =
  'w-full rounded-[var(--cxs-radius-md)] border border-[var(--cxs-color-border)] ' +
  'bg-[var(--cxs-color-surface)] px-2 py-1 text-xs text-[var(--cxs-color-on-surface)] ' +
  'placeholder:text-[var(--cxs-color-on-surface-muted)] focus-visible:outline focus-visible:outline-2 ' +
  'focus-visible:outline-offset-2 focus-visible:outline-[var(--cxs-color-focus)]';

const BODY_ROW_BASE_CLASSES = 'border-b border-[var(--cxs-color-border)] last:border-b-0';
const BODY_ROW_STRIPED_CLASSES = 'odd:bg-[var(--cxs-color-surface)] even:bg-[var(--cxs-color-surface-hover)]';

const BODY_CELL_BASE_CLASSES = 'px-3 py-2 align-top';
const BODY_CELL_COMPACT_CLASSES = 'px-2 py-1.5';

const ALIGN_CLASSES: Record<CxsDataTableAlign, string> = {
  left: 'text-left',
  center: 'text-center',
  right: 'text-right'
};

const EMPTY_ROW_CLASSES = 'text-sm text-[var(--cxs-color-on-surface-muted)]';
const PAGINATION_CLASSES =
  'mt-4 flex flex-wrap items-center justify-between gap-3 text-sm text-[var(--cxs-color-on-surface)]';
const PAGE_BUTTON_CLASSES =
  'inline-flex items-center justify-center rounded-[var(--cxs-radius-md)] border border-[var(--cxs-color-border)] ' +
  'px-3 py-1.5 text-sm transition-colors hover:bg-[var(--cxs-color-surface-hover)] ' +
  'disabled:cursor-not-allowed disabled:opacity-60';
const PAGE_SELECT_CLASSES =
  'rounded-[var(--cxs-radius-md)] border border-[var(--cxs-color-border)] bg-[var(--cxs-color-surface)] ' +
  'px-2 py-1 text-sm';
const TOOLBAR_CLASSES =
  'mb-3 flex flex-wrap items-center justify-between gap-3 text-sm text-[var(--cxs-color-on-surface)]';
const TOOLBAR_GROUP_CLASSES = 'flex flex-wrap items-center gap-2';
const TOOLBAR_INPUT_CLASSES =
  'w-full rounded-[var(--cxs-radius-md)] border border-[var(--cxs-color-border)] ' +
  'bg-[var(--cxs-color-surface)] px-3 py-2 text-sm text-[var(--cxs-color-on-surface)] ' +
  'placeholder:text-[var(--cxs-color-on-surface-muted)] focus-visible:outline focus-visible:outline-2 ' +
  'focus-visible:outline-offset-2 focus-visible:outline-[var(--cxs-color-focus)]';
const TOOLBAR_BUTTON_CLASSES =
  'inline-flex items-center justify-center rounded-[var(--cxs-radius-md)] border border-[var(--cxs-color-border)] ' +
  'px-3 py-2 text-sm transition-colors hover:bg-[var(--cxs-color-surface-hover)]';
const BULK_BAR_CLASSES =
  'mb-3 flex flex-wrap items-center justify-between gap-3 rounded-[var(--cxs-radius-md)] ' +
  'border border-[var(--cxs-color-border)] bg-[var(--cxs-color-surface)] px-3 py-2 text-sm';
const RESIZE_HANDLE_CLASSES =
  'absolute right-0 top-0 h-full w-2 cursor-col-resize touch-none';

@Component({
  selector: 'cxs-data-table',
  standalone: true,
  templateUrl: './data-table.component.html',
  imports: [NgTemplateOutlet],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CxsDataTableComponent implements OnChanges {
  @Input() columns: CxsDataTableColumn[] = [];
  @Input() data: Array<Record<string, unknown>> = [];
  @Input() caption?: string;
  @Input() ariaLabel = 'Data table';
  @Input() striped = false;
  @Input() bordered = false;
  @Input() compact = false;
  @Input() loading = false;
  @Input() emptyMessage = 'No data available';
  @Input() emptyCell = '—';

  @Input() pageSize = 10;
  @Input() pageIndex = 1;
  @Input() pageSizeOptions: number[] = [10, 20, 50];
  @Input() showPagination = true;
  @Input() showPageSize = true;
  @Input() manualPagination = false;
  @Input() total?: number;

  @Input() sortKey?: string;
  @Input() sortDirection: CxsDataTableSortDirection = 'asc';
  @Input() manualSort = false;

  @Input() showToolbar = true;
  @Input() showFilters = true;
  @Input() showColumnVisibility = true;
  @Input() showGlobalSearch = true;
  @Input() manualFilter = false;

  @Input() selectable = false;
  @Input() rowKey = 'id';
  @Input() selectedKeys: Array<string | number> = [];
  @Input() bulkActions: Array<{ id: string; label: string }> = [];

  @Output() pageChange = new EventEmitter<number>();
  @Output() pageSizeChange = new EventEmitter<number>();
  @Output() sortChange = new EventEmitter<CxsDataTableSort>();
  @Output() filterChange = new EventEmitter<{
    global: string;
    columns: Record<string, string>;
  }>();
  @Output() selectionChange = new EventEmitter<Array<string | number>>();
  @Output() bulkAction = new EventEmitter<{
    id: string;
    selected: Array<Record<string, unknown>>;
  }>();

  @ContentChildren(CxsDataTableCellDirective)
  private readonly cellTemplates?: QueryList<CxsDataTableCellDirective>;

  protected currentPage = 1;
  protected currentPageSize = 10;
  protected globalFilter = '';
  protected columnFilters: Record<string, string> = {};
  protected columnVisibility: Record<string, boolean> = {};
  protected columnWidths: Record<string, string> = {};
  protected isResizing = false;
  protected resizingColumn?: string;
  protected pinnedOffsetsLeft: Record<string, number> = {};
  protected pinnedOffsetsRight: Record<string, number> = {};
  protected filtersOpen = true;

  private resizeStartX = 0;
  private resizeStartWidth = 0;

  constructor(@Attribute('class') private readonly hostClass: string | null) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['pageIndex']) {
      this.currentPage = Math.max(1, this.pageIndex);
    }
    if (changes['pageSize']) {
      this.currentPageSize = Math.max(1, this.pageSize);
    }
    if (changes['columns']) {
      this.initializeVisibility();
      this.initializeWidths();
      this.updatePinnedOffsets();
    }
    if (changes['showFilters']) {
      this.filtersOpen = this.showFilters;
    }
    if (changes['selectedKeys']) {
      this.selectedKeys = [...this.selectedKeys];
    }
  }

  get wrapperClass(): string {
    return [
      WRAPPER_BASE_CLASSES,
      this.bordered ? WRAPPER_BORDERED_CLASSES : '',
      this.hostClass
    ]
      .filter(Boolean)
      .join(' ');
  }

  get tableClass(): string {
    return [TABLE_BASE_CLASSES, this.compact ? TABLE_COMPACT_CLASSES : '']
      .filter(Boolean)
      .join(' ');
  }

  get headerRowClass(): string {
    return HEADER_ROW_CLASSES;
  }

  get bodyRowClass(): string {
    return [
      BODY_ROW_BASE_CLASSES,
      this.striped ? BODY_ROW_STRIPED_CLASSES : ''
    ]
      .filter(Boolean)
      .join(' ');
  }

  get emptyRowClass(): string {
    return EMPTY_ROW_CLASSES;
  }

  get paginationClass(): string {
    return PAGINATION_CLASSES;
  }

  get pageButtonClass(): string {
    return PAGE_BUTTON_CLASSES;
  }

  get pageSelectClass(): string {
    return PAGE_SELECT_CLASSES;
  }

  get toolbarClass(): string {
    return TOOLBAR_CLASSES;
  }

  get toolbarGroupClass(): string {
    return TOOLBAR_GROUP_CLASSES;
  }

  get toolbarInputClass(): string {
    return TOOLBAR_INPUT_CLASSES;
  }

  get toolbarButtonClass(): string {
    return TOOLBAR_BUTTON_CLASSES;
  }

  get bulkBarClass(): string {
    return BULK_BAR_CLASSES;
  }

  get resizeHandleClass(): string {
    return RESIZE_HANDLE_CLASSES;
  }

  get colSpan(): number {
    return Math.max(this.visibleColumns.length + (this.selectable ? 1 : 0), 1);
  }

  get totalItems(): number {
    if (this.manualPagination && this.total !== undefined) {
      return this.total;
    }

    return this.data.length;
  }

  get totalPages(): number {
    return Math.max(1, Math.ceil(this.totalItems / this.currentPageSize));
  }

  get pageLabel(): string {
    return `Page ${this.currentPage} of ${this.totalPages}`;
  }

  get displayRows(): Array<Record<string, unknown>> {
    const filtered = this.manualFilter ? this.data : this.getFilteredData(this.data);
    const sorted = this.manualSort ? filtered : this.getSortedData(filtered);
    if (this.manualPagination) {
      return sorted;
    }

    const start = (this.currentPage - 1) * this.currentPageSize;
    return sorted.slice(start, start + this.currentPageSize);
  }

  get visibleColumns(): CxsDataTableColumn[] {
    return this.columns.filter((column) => this.columnVisibility[column.key] !== false);
  }

  get selectedCount(): number {
    return this.selectedKeys.length;
  }

  get allVisibleSelected(): boolean {
    if (!this.displayRows.length) {
      return false;
    }

    return this.displayRows.every((row) => this.isSelected(row));
  }

  get someVisibleSelected(): boolean {
    return this.displayRows.some((row) => this.isSelected(row)) && !this.allVisibleSelected;
  }

  headerCellClass(column: CxsDataTableColumn): string {
    return [
      HEADER_CELL_BASE_CLASSES,
      ALIGN_CLASSES[column.align ?? 'left'],
      column.headerClass ?? ''
    ]
      .filter(Boolean)
      .join(' ');
  }

  headerButtonClass(): string {
    return HEADER_BUTTON_CLASSES;
  }

  headerFilterInputClass(): string {
    return HEADER_FILTER_INPUT_CLASSES;
  }

  bodyCellClass(column: CxsDataTableColumn): string {
    return [
      BODY_CELL_BASE_CLASSES,
      this.compact ? BODY_CELL_COMPACT_CLASSES : '',
      ALIGN_CLASSES[column.align ?? 'left'],
      column.cellClass ?? ''
    ]
      .filter(Boolean)
      .join(' ');
  }

  cellTemplate(columnKey: string): TemplateRef<CxsDataTableCellContext> | null {
    if (!this.cellTemplates) {
      return null;
    }

    return this.cellTemplates.find((template) => template.columnKey === columnKey)?.template ?? null;
  }

  cellValue(row: Record<string, unknown>, column: CxsDataTableColumn): string {
    const value = row[column.key];
    if (column.formatter) {
      return column.formatter(value, row);
    }

    if (value === null || value === undefined || value === '') {
      return this.emptyCell;
    }

    return String(value);
  }

  columnWidth(column: CxsDataTableColumn): string | null {
    return this.columnWidths[column.key] ?? column.width ?? null;
  }

  columnMinWidth(column: CxsDataTableColumn): string | null {
    if (column.minWidth) {
      return `${column.minWidth}px`;
    }
    return null;
  }

  pinnedStyle(column: CxsDataTableColumn): Record<string, string> | null {
    if (!column.pinned) {
      return null;
    }

    if (column.pinned === 'left') {
      return { left: `${this.pinnedOffsetsLeft[column.key] ?? 0}px` };
    }

    return { right: `${this.pinnedOffsetsRight[column.key] ?? 0}px` };
  }

  pinnedLeft(column: CxsDataTableColumn): string | null {
    const style = this.pinnedStyle(column);
    return style ? style['left'] ?? null : null;
  }

  pinnedRight(column: CxsDataTableColumn): string | null {
    const style = this.pinnedStyle(column);
    return style ? style['right'] ?? null : null;
  }

  pinnedClass(column: CxsDataTableColumn): string {
    if (!column.pinned) {
      return '';
    }

    return 'sticky z-10';
  }

  ariaSort(column: CxsDataTableColumn): 'ascending' | 'descending' | 'none' | null {
    if (!column.sortable) {
      return null;
    }

    if (this.sortKey !== column.key) {
      return 'none';
    }

    return this.sortDirection === 'asc' ? 'ascending' : 'descending';
  }

  onSort(column: CxsDataTableColumn): void {
    if (!column.sortable) {
      return;
    }

    if (this.sortKey === column.key) {
      this.sortDirection = this.sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      this.sortKey = column.key;
      this.sortDirection = 'asc';
    }

    this.sortChange.emit({
      key: this.sortKey,
      direction: this.sortDirection
    });
  }

  goToPage(page: number): void {
    const nextPage = Math.min(Math.max(1, page), this.totalPages);
    this.currentPage = nextPage;
    this.pageChange.emit(nextPage);
  }

  nextPage(): void {
    this.goToPage(this.currentPage + 1);
  }

  previousPage(): void {
    this.goToPage(this.currentPage - 1);
  }

  onPageSizeChange(value: string): void {
    const nextSize = Number(value);
    if (!Number.isFinite(nextSize) || nextSize <= 0) {
      return;
    }

    this.currentPageSize = nextSize;
    this.pageSizeChange.emit(nextSize);
    this.goToPage(1);
  }

  onGlobalFilterChange(value: string): void {
    this.globalFilter = value;
    this.emitFilterChange();
    this.goToPage(1);
  }

  onColumnFilterChange(columnKey: string, value: string): void {
    this.columnFilters[columnKey] = value;
    this.emitFilterChange();
    this.goToPage(1);
  }

  columnFilterValue(columnKey: string): string {
    return this.columnFilters[columnKey] || '';
  }

  toggleColumnVisibility(columnKey: string): void {
    this.columnVisibility[columnKey] = !this.columnVisibility[columnKey];
    this.updatePinnedOffsets();
  }

  toggleSelectAll(): void {
    if (this.allVisibleSelected) {
      this.selectedKeys = this.selectedKeys.filter(
        (key) => !this.displayRows.some((row) => this.rowIdentifier(row) === key)
      );
    } else {
      const keysToAdd = this.displayRows
        .map((row) => this.rowIdentifier(row))
        .filter((key) => !this.selectedKeys.includes(key));
      this.selectedKeys = [...this.selectedKeys, ...keysToAdd];
    }

    this.selectionChange.emit([...this.selectedKeys]);
  }

  toggleRowSelection(row: Record<string, unknown>): void {
    const key = this.rowIdentifier(row);
    if (this.selectedKeys.includes(key)) {
      this.selectedKeys = this.selectedKeys.filter((id) => id !== key);
    } else {
      this.selectedKeys = [...this.selectedKeys, key];
    }

    this.selectionChange.emit([...this.selectedKeys]);
  }

  isSelected(row: Record<string, unknown>): boolean {
    return this.selectedKeys.includes(this.rowIdentifier(row));
  }

  runBulkAction(actionId: string): void {
    this.bulkAction.emit({
      id: actionId,
      selected: this.data.filter((row) => this.selectedKeys.includes(this.rowIdentifier(row)))
    });
  }

  onResizeStart(event: MouseEvent, column: CxsDataTableColumn): void {
    if (column.resizable === false) {
      return;
    }

    event.preventDefault();
    const header = (event.target as HTMLElement).closest('th') as HTMLElement | null;
    if (!header) {
      return;
    }

    this.isResizing = true;
    this.resizingColumn = column.key;
    this.resizeStartX = event.clientX;
    this.resizeStartWidth = header.getBoundingClientRect().width;

    const onMove = (moveEvent: MouseEvent) => {
      if (!this.isResizing || !this.resizingColumn) {
        return;
      }
      const delta = moveEvent.clientX - this.resizeStartX;
      const minWidth = column.minWidth ?? 80;
      const nextWidth = Math.max(minWidth, this.resizeStartWidth + delta);
      this.columnWidths[this.resizingColumn] = `${Math.round(nextWidth)}px`;
      this.updatePinnedOffsets();
    };

    const onUp = () => {
      this.isResizing = false;
      this.resizingColumn = undefined;
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
    };

    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  }

  private getSortedData(rows: Array<Record<string, unknown>>): Array<Record<string, unknown>> {
    if (!this.sortKey) {
      return rows;
    }

    const direction = this.sortDirection === 'asc' ? 1 : -1;
    return [...rows].sort((a, b) => {
      const valueA = a[this.sortKey ?? ''];
      const valueB = b[this.sortKey ?? ''];
      const normalizedA = valueA === null || valueA === undefined ? '' : String(valueA);
      const normalizedB = valueB === null || valueB === undefined ? '' : String(valueB);
      return normalizedA.localeCompare(normalizedB, undefined, { numeric: true }) * direction;
    });
  }

  private getFilteredData(rows: Array<Record<string, unknown>>): Array<Record<string, unknown>> {
    const global = this.globalFilter.trim().toLowerCase();
    const filters = this.columnFilters;

    return rows.filter((row) => {
      if (global) {
        const matchesGlobal = this.visibleColumns.some((column) => {
          const value = row[column.key];
          return String(value ?? '').toLowerCase().includes(global);
        });
        if (!matchesGlobal) {
          return false;
        }
      }

      return this.visibleColumns.every((column) => {
        if (!column.filterable) {
          return true;
        }
        const filterValue = (filters[column.key] ?? '').trim().toLowerCase();
        if (!filterValue) {
          return true;
        }
        const raw = row[column.key];
        const normalized = String(raw ?? '').toLowerCase();
        if (column.filterType === 'select') {
          return normalized === filterValue;
        }
        return normalized.includes(filterValue);
      });
    });
  }

  private emitFilterChange(): void {
    this.filterChange.emit({
      global: this.globalFilter,
      columns: { ...this.columnFilters }
    });
  }

  private initializeVisibility(): void {
    this.columnVisibility = this.columns.reduce((acc, column) => {
      acc[column.key] = column.visible !== false;
      return acc;
    }, {} as Record<string, boolean>);
  }

  private initializeWidths(): void {
    this.columnWidths = this.columns.reduce((acc, column) => {
      if (column.width) {
        acc[column.key] = column.width;
      }
      return acc;
    }, {} as Record<string, string>);
  }

  private updatePinnedOffsets(): void {
    const leftOffsets: Record<string, number> = {};
    const rightOffsets: Record<string, number> = {};
    let left = 0;
    let right = 0;
    const columns = this.visibleColumns;

    columns.forEach((column) => {
      if (column.pinned === 'left') {
        leftOffsets[column.key] = left;
        left += this.getWidthValue(column);
      }
    });

    [...columns].reverse().forEach((column) => {
      if (column.pinned === 'right') {
        rightOffsets[column.key] = right;
        right += this.getWidthValue(column);
      }
    });

    this.pinnedOffsetsLeft = leftOffsets;
    this.pinnedOffsetsRight = rightOffsets;
  }

  private getWidthValue(column: CxsDataTableColumn): number {
    const width = this.columnWidths[column.key] ?? column.width;
    if (!width) {
      return 160;
    }
    const match = width.match(/(\d+)(px)?/);
    if (match) {
      return Number(match[1]);
    }
    return 160;
  }

  private rowIdentifier(row: Record<string, unknown>): string | number {
    const value = row[this.rowKey];
    if (value === undefined || value === null) {
      return JSON.stringify(row);
    }
    return value as string | number;
  }
}

import {
  Attribute,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  Output,
  QueryList,
  ViewChildren
} from '@angular/core';

export type CxsMenubarSize = 'sm' | 'md' | 'lg';
export type CxsMenubarVariant = 'default' | 'surface';

export interface CxsMenubarItem {
  label: string;
  href?: string;
  target?: string;
  rel?: string;
  ariaLabel?: string;
  disabled?: boolean;
  active?: boolean;
}

const BAR_BASE_CLASSES =
  'm-0 flex list-none flex-wrap items-center gap-1 rounded-[var(--cxs-radius-md)] border border-transparent p-1';

const BAR_SIZE_CLASSES: Record<CxsMenubarSize, string> = {
  sm: 'text-xs',
  md: 'text-sm',
  lg: 'text-base'
};

const BAR_VARIANT_CLASSES: Record<CxsMenubarVariant, string> = {
  default: 'bg-transparent',
  surface:
    'bg-[var(--cxs-color-surface)] border-[var(--cxs-color-border)] shadow-[var(--cxs-shadow-sm)]'
};

const ITEM_BASE_CLASSES =
  'inline-flex items-center gap-2 rounded-[var(--cxs-radius-md)] px-3 py-1.5 font-medium ' +
  'transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 ' +
  'focus-visible:outline-[var(--cxs-color-focus)]';

const ITEM_SIZE_CLASSES: Record<CxsMenubarSize, string> = {
  sm: 'px-2.5 py-1 text-xs',
  md: 'px-3 py-1.5 text-sm',
  lg: 'px-4 py-2 text-base'
};

const ITEM_ACTIVE_CLASSES =
  'bg-[var(--cxs-color-primary-ghost)] text-[var(--cxs-color-primary)]';
const ITEM_INACTIVE_CLASSES =
  'text-[var(--cxs-color-on-surface)] hover:bg-[var(--cxs-color-surface-hover)]';
const ITEM_DISABLED_CLASSES =
  'text-[var(--cxs-color-on-surface-muted)] opacity-60 pointer-events-none';

@Component({
  selector: 'cxs-menubar',
  standalone: true,
  templateUrl: './menubar.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CxsMenubarComponent {
  @Input() items: CxsMenubarItem[] = [];
  @Input() ariaLabel = 'Menubar';
  @Input() size: CxsMenubarSize = 'md';
  @Input() variant: CxsMenubarVariant = 'default';
  @Input() disabled = false;

  @Output() itemSelected = new EventEmitter<CxsMenubarItem>();

  @ViewChildren('menuItem', { read: ElementRef })
  private readonly menuItems?: QueryList<ElementRef<HTMLElement>>;

  constructor(@Attribute('class') private readonly hostClass: string | null) {}

  get menubarClass(): string {
    return [
      BAR_BASE_CLASSES,
      BAR_SIZE_CLASSES[this.size],
      BAR_VARIANT_CLASSES[this.variant],
      this.hostClass
    ]
      .filter(Boolean)
      .join(' ');
  }

  isItemDisabled(item: CxsMenubarItem): boolean {
    return this.disabled || !!item.disabled;
  }

  getItemClass(item: CxsMenubarItem): string {
    return [
      ITEM_BASE_CLASSES,
      ITEM_SIZE_CLASSES[this.size],
      item.active ? ITEM_ACTIVE_CLASSES : ITEM_INACTIVE_CLASSES,
      this.isItemDisabled(item) ? ITEM_DISABLED_CLASSES : ''
    ]
      .filter(Boolean)
      .join(' ');
  }

  getItemHref(item: CxsMenubarItem): string | null {
    if (item.href && !this.isItemDisabled(item)) {
      return item.href;
    }

    return null;
  }

  getItemRel(item: CxsMenubarItem): string | null {
    if (item.target === '_blank') {
      return item.rel ?? 'noopener noreferrer';
    }

    return item.rel ?? null;
  }

  onItemClick(item: CxsMenubarItem, event: Event): void {
    if (this.isItemDisabled(item)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }

    this.itemSelected.emit(item);
  }

  onKeydown(event: KeyboardEvent): void {
    if (this.disabled) {
      return;
    }

    if (typeof document === 'undefined') {
      return;
    }

    const keys = ['ArrowRight', 'ArrowLeft', 'Home', 'End'];
    if (!keys.includes(event.key)) {
      return;
    }

    const items = this.getFocusableItems();
    if (!items.length) {
      return;
    }

    const currentIndex = items.findIndex((item) => item === document.activeElement);
    let nextIndex = 0;

    switch (event.key) {
      case 'Home':
        nextIndex = 0;
        break;
      case 'End':
        nextIndex = items.length - 1;
        break;
      case 'ArrowRight':
        nextIndex = currentIndex >= 0 ? (currentIndex + 1) % items.length : 0;
        break;
      case 'ArrowLeft':
        nextIndex = currentIndex >= 0 ? (currentIndex - 1 + items.length) % items.length : items.length - 1;
        break;
    }

    items[nextIndex]?.focus();
    event.preventDefault();
  }

  private getFocusableItems(): HTMLElement[] {
    return (this.menuItems?.toArray() ?? [])
      .map((item) => item.nativeElement)
      .filter((item) => !item.hasAttribute('data-disabled'));
  }
}

import { Attribute, ChangeDetectionStrategy, Component, Input } from '@angular/core';

export type CxsTableAlign = 'left' | 'center' | 'right';

export interface CxsTableColumn {
  key: string;
  label: string;
  align?: CxsTableAlign;
  width?: string;
  headerClass?: string;
  cellClass?: string;
}

const WRAPPER_BASE_CLASSES = 'w-full overflow-hidden';
const WRAPPER_BORDERED_CLASSES =
  'rounded-[var(--cxs-radius-md)] border border-[var(--cxs-color-border)]';

const TABLE_BASE_CLASSES = 'w-full border-collapse text-sm text-[var(--cxs-color-on-surface)]';
const TABLE_COMPACT_CLASSES = 'text-xs';

const HEADER_ROW_CLASSES =
  'border-b border-[var(--cxs-color-border)] text-xs uppercase tracking-[0.2em] ' +
  'text-[var(--cxs-color-on-surface-muted)]';
const HEADER_CELL_BASE_CLASSES = 'px-3 py-2 text-left font-semibold';

const BODY_ROW_BASE_CLASSES = 'border-b border-[var(--cxs-color-border)] last:border-b-0';
const BODY_ROW_STRIPED_CLASSES = 'odd:bg-[var(--cxs-color-surface)] even:bg-[var(--cxs-color-surface-hover)]';

const BODY_CELL_BASE_CLASSES = 'px-3 py-2 align-top';
const BODY_CELL_COMPACT_CLASSES = 'px-2 py-1.5';

const ALIGN_CLASSES: Record<CxsTableAlign, string> = {
  left: 'text-left',
  center: 'text-center',
  right: 'text-right'
};

const EMPTY_ROW_CLASSES = 'text-sm text-[var(--cxs-color-on-surface-muted)]';

@Component({
  selector: 'cxs-table',
  standalone: true,
  templateUrl: './table.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CxsTableComponent {
  @Input() columns: CxsTableColumn[] = [];
  @Input() data: Array<Record<string, unknown>> = [];
  @Input() caption?: string;
  @Input() ariaLabel = 'Table';
  @Input() striped = false;
  @Input() bordered = false;
  @Input() compact = false;
  @Input() emptyMessage = 'No data available';
  @Input() emptyCell = '—';

  constructor(@Attribute('class') private readonly hostClass: string | null) {}

  get wrapperClass(): string {
    return [
      WRAPPER_BASE_CLASSES,
      this.bordered ? WRAPPER_BORDERED_CLASSES : '',
      this.hostClass
    ]
      .filter(Boolean)
      .join(' ');
  }

  get tableClass(): string {
    return [TABLE_BASE_CLASSES, this.compact ? TABLE_COMPACT_CLASSES : '']
      .filter(Boolean)
      .join(' ');
  }

  get headerRowClass(): string {
    return HEADER_ROW_CLASSES;
  }

  get bodyRowClass(): string {
    return [
      BODY_ROW_BASE_CLASSES,
      this.striped ? BODY_ROW_STRIPED_CLASSES : ''
    ]
      .filter(Boolean)
      .join(' ');
  }

  get emptyRowClass(): string {
    return EMPTY_ROW_CLASSES;
  }

  get colSpan(): number {
    return Math.max(this.columns.length, 1);
  }

  headerCellClass(column: CxsTableColumn): string {
    return [
      HEADER_CELL_BASE_CLASSES,
      ALIGN_CLASSES[column.align ?? 'left'],
      column.headerClass ?? ''
    ]
      .filter(Boolean)
      .join(' ');
  }

  bodyCellClass(column: CxsTableColumn): string {
    return [
      BODY_CELL_BASE_CLASSES,
      this.compact ? BODY_CELL_COMPACT_CLASSES : '',
      ALIGN_CLASSES[column.align ?? 'left'],
      column.cellClass ?? ''
    ]
      .filter(Boolean)
      .join(' ');
  }

  cellValue(row: Record<string, unknown>, column: CxsTableColumn): string {
    const value = row[column.key];
    if (value === null || value === undefined || value === '') {
      return this.emptyCell;
    }

    return String(value);
  }
}

