export type CxsToastVariant = 'info' | 'neutral' | 'danger';
export type CxsToastCloseReason = 'dismiss' | 'timeout';
export type CxsToastPosition =
  | 'bottom-right'
  | 'bottom'
  | 'bottom-left'
  | 'top-right'
  | 'top'
  | 'top-left'
  | 'right'
  | 'left'
